const item = $input.first().json;

const execution = item.execution || {};
const workflow = item.workflow || {};
const error = execution.error || {};

const workflowName = workflow.name || 'Workflow desconocido';
const workflowId = workflow.id || 'N/A';
const executionId = execution.id || 'N/A';
const executionUrl = execution.url || '';
const errorMessage = error.message || 'Error no especificado';
const errorStack = error.stack || '';
const lastNodeExecuted = execution.lastNodeExecuted || 'Desconocido';
const timestamp = new Date().toISOString();

const alertSubject = `🚨 [ALERTA PTD] Fallo en ${workflowName} (Nodo: ${lastNodeExecuted})`;
const alertHtml = `
  <div style="font-family: Arial, sans-serif; max-width: 650px; padding: 20px; border: 1px solid #e2e8f0; border-radius: 8px;">
    <h2 style="color: #e11d48; margin-top: 0;">🚨 Incidencia en Automatización PTD</h2>
    <p>Se ha producido un error durante la ejecución de un proceso automático:</p>
    <table style="width: 100%; border-collapse: collapse; margin-bottom: 20px;">
      <tr><td style="padding: 8px; font-weight: bold; width: 160px;">Workflow:</td><td style="padding: 8px;">${workflowName}</td></tr>
      <tr style="background: #f8fafc;"><td style="padding: 8px; font-weight: bold;">Último Nodo:</td><td style="padding: 8px; color: #b91c1c;"><strong>${lastNodeExecuted}</strong></td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Mensaje de Error:</td><td style="padding: 8px; color: #dc2626;">${errorMessage}</td></tr>
      <tr style="background: #f8fafc;"><td style="padding: 8px; font-weight: bold;">Fecha / Hora:</td><td style="padding: 8px;">${timestamp}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">ID de Ejecución:</td><td style="padding: 8px;"><code>${executionId}</code></td></tr>
    </table>
    ${executionUrl ? `<p><a href="${executionUrl}" style="background: #2563eb; color: #fff; padding: 10px 18px; text-decoration: none; border-radius: 6px; font-weight: bold; display: inline-block;">Ver Ejecución en n8n ➔</a></p>` : ''}
    <hr style="border: 0; border-top: 1px solid #e2e8f0; margin: 20px 0;"/>
    <p style="font-size: 11px; color: #64748b;">Sistema de Observabilidad y Recuperación de Fallos — PorTusDerechos</p>
  </div>
`;

return {
  workflowName,
  workflowId,
  executionId,
  executionUrl,
  lastNodeExecuted,
  errorMessage,
  errorStack,
  timestamp,
  alertSubject,
  alertHtml
};

